function newGame(){score=0;lives=3;level=1;ended=false;running=false;started=false;paddle.x=W/2-paddle.w/2;makeBricks();resetBall();hud();show('Ready when you are','BREAK THE BRICKS','Move your paddle to keep the ball in play. Clear both levels to win.','Start game')}
