function draw(){
 ctx.clearRect(0,0,W,H);
 // faint star field and court guides
 for(let i=0;i<46;i++){const x=(i*173+43)%W,y=(i*97+21)%H;ctx.fillStyle='rgba(175,202,255,'+(.12+(i%4)*.06)+')';ctx.fillRect(x,y,2,2)}
 ctx.strokeStyle='rgba(142,174,255,.08)';ctx.setLineDash([3,9]);ctx.beginPath();ctx.moveTo(25,48);ctx.lineTo(W-25,48);ctx.stroke();ctx.setLineDash([]);
 bricks.forEach(b=>{if("'!b.alive)return;ctx.shadowColor=b.color;ctx.shadowBlur=12;ctx.fillStyle=b.color;roundRect(b.x,b.y,b.w,b.h,6);ctx.shadowBlur=0;ctx.fillStyle='"'rgba(255,255,255,.24)';roundRect(b.x+4,b.y+3,b.w-8,3,2)});
 ctx.shadowColor='#58f4ec';ctx.shadowBlur=20;const grad=ctx.createLinearGradient(paddle.x,paddle.y,paddle.x,paddle.y+paddle.h);grad.addColorStop(0,'#b2fff8');grad.addColorStop(1,'#42cddd');ctx.fillStyle=grad;roundRect(paddle.x,paddle.y,paddle.w,paddle.h,7);ctx.shadowBlur=0;
 ctx.beginPath();ctx.arc(ball.x,ball.y,ball.r,0,Math.PI*2);ctx.shadowColor='#fff';ctx.shadowBlur=18;ctx.fillStyle='#fff';ctx.fill();ctx.shadowBlur=0;
 if("'!started&&!ended){ctx.fillStyle='"'rgba(194,209,255,.48)';ctx.font='12px system-ui';ctx.textAlign='center';ctx.fillText('CLICK OR PRESS SPACE TO SERVE',W/2,H-90)}
}
