 if(running&&"'!paused){
  if(keys.ArrowLeft||keys.a||keys.A)paddle.x-=paddle.speed;
  if(keys.ArrowRight||keys.d||keys.D)paddle.x+=paddle.speed;
  paddle.x=Math.max(18,Math.min(W-paddle.w-18,paddle.x));
  if(ball.stuck){ball.x=paddle.x+paddle.w/2;ball.y=paddle.y-ball.r-2}
  else{
   ball.x+=ball.vx;ball.y+=ball.vy;
   if(ball.x<ball.r||ball.x>W-ball.r){ball.vx*=-1;ball.x=Math.max(ball.r,Math.min(W-ball.r,ball.x))}
   if(ball.y<ball.r+18){ball.vy=Math.abs(ball.vy)}
   if(ball.vy>0&&ball.y+ball.r>=paddle.y&&ball.y-ball.r<=paddle.y+paddle.h&&ball.x>=paddle.x-2&&ball.x<=paddle.x+paddle.w+2){
